<?php
defined('BASEPATH') OR exit('No direct script access allowed');
$summary = $insights['summary'] ?? [];
$photo_url = function ($member) {
	$path = $member['photo_local_path'] ?? '';
	if ($path !== '') return base_url(implode('/', array_map('rawurlencode', explode('/', str_replace('\\', '/', trim($path, '/'))))));
	$source = $member['photo_source_path'] ?? ($member['photo_path'] ?? '');
	if ($source !== '' && strpos($source, 'assets/') === 0) return base_url(implode('/', array_map('rawurlencode', explode('/', str_replace('\\', '/', trim($source, '/'))))));
	if ($source !== '') return base_url('assets/uploads/inlislite/source_mirror/' . implode('/', array_map('rawurlencode', explode('/', str_replace('\\', '/', trim($source, '/'))))));
	return '';
};
$initials = function ($name) {
	$parts = preg_split('/\s+/', trim((string) $name));
	$letters = '';
	foreach (array_slice(array_filter($parts), 0, 2) as $part) $letters .= mb_strtoupper(mb_substr($part, 0, 1));
	return $letters ?: '?';
};
$member_avatar = function ($member, $class = '') use ($photo_url, $initials) {
	$url = $photo_url($member);
	if ($url) return '<span class="patron-avatar ' . html_escape($class) . '"><img src="' . html_escape($url) . '" alt="Foto ' . html_escape($member['full_name'] ?? 'member') . '"></span>';
	return '<span class="patron-avatar patron-avatar-fallback ' . html_escape($class) . '">' . html_escape($initials($member['full_name'] ?? '')) . '</span>';
};
$render_rank = function ($items, $metric, $caption, $icon, $tone) use ($member_avatar) { ?>
	<div class="patron-rank-list">
		<?php if (empty($items)): ?><div class="patron-empty"><i class="ti ti-chart-bar-off"></i><span>Belum ada data pada periode ini.</span></div><?php endif; ?>
		<?php foreach ($items as $index => $member): ?>
			<a class="patron-rank-row" href="<?= base_url('members/detail/' . (int) $member['id']); ?>">
				<span class="patron-rank-number <?= $index < 3 ? 'is-top' : ''; ?>"><?= $index + 1; ?></span>
				<?= $member_avatar($member); ?>
				<span class="patron-rank-copy"><strong><?= html_escape($member['full_name']); ?></strong><small><?= html_escape($member['member_no'] ?: 'Nomor anggota belum tercatat'); ?></small></span>
				<span class="patron-rank-value <?= html_escape($tone); ?>"><b><?= number_format((int) ($member[$metric] ?? 0), 0, ',', '.'); ?></b><small><?= html_escape($caption); ?></small></span>
			</a>
		<?php endforeach; ?>
	</div>
<?php };
$champion = $insights['patron_of_month'] ?? null;
$champions = $insights['patron_champions'] ?? [];
$active_tab = $active_tab ?? 'overview';
$scope_label = ($filters['scope'] ?? 'month') === 'all' ? 'Sepanjang data tersedia' : 'Bulan ' . html_escape($period['period_label']);
$tab_url = function ($tab) use ($filters) {
	$query = $filters;
	$query['tab'] = $tab;
	return base_url('reports/pemustaka?' . http_build_query($query));
};
